Here are the unit tests for the `is_palindrome` function using Python's `unittest` framework:

```python
import unittest

def is_palindrome(s):
    return s == s[::-1]

class TestIsPalindrome(unittest.TestCase):
    def test_empty_string(self):
        self.assertTrue(is_palindrome(""))

    def test_single_character(self):
        self.assertTrue(is_palindrome("a"))

    def test_palindrome_even_length(self):
        self.assertTrue(is_palindrome("abba"))

    def test_palindrome_odd_length(self):
        self.assertTrue(is_palindrome("aba"))

    def test_not_palindrome(self):
        self.assertFalse(is_palindrome("abc"))

    def test_palindrome_with_spaces(self):
        # Note: The current implementation is case-sensitive and space-sensitive.
        # "a b a" is not equal to "a b a"[::-1] which is "a b a", so it passes.
        # But "ab ba" reversed is "ab ba", so it passes.
        # Let's test a case that fails due to case sensitivity.
        self.assertFalse(is_palindrome("Abba"))

    def test_palindrome_case_sensitive_false(self):
        self.assertFalse(is_palindrome("Abba"))

if __name__ == '__main__':
    unittest.main()
